    helpTopicSearchWorkspaceTitle: "Search workspace",
    helpTopicSearchWorkspaceText: "This is where you build a Bluesky search, keep reusable search forms locally, and refine results with Threadline-specific filters.",
    helpTopicSearchWorkspaceBullet1: "Mode decides whether you search the network, only one account's posts, only reposts, or a hashtag-focused search.",
    helpTopicSearchWorkspaceBullet2: "shared bsky search URL can import a shared Bluesky search and prefill the form automatically.",
    helpTopicSearchWorkspaceBullet3: "Search text is your main topic or keyword and is used like a normal Bluesky text search.",
    helpTopicSearchWorkspaceBullet4: "Account limits the search to one account or acts as the feed source in the account modes.",
    helpTopicSearchWorkspaceBullet5: "Open hashtag filter opens the hashtag manager for this search form without filling the whole left column.",
    helpTopicSearchWorkspaceBullet6: "Media, post type, and does not contain are extra filters that narrow results by images, replies, quotes, reposts, or excluded terms.",
    helpTopicSearchWorkspaceBullet7: "Mentions account, language, domain, and link URL help with more precise cases such as mentions, websites, or language-specific searches.",
    helpTopicSearchWorkspaceBullet8: "From and Until limit the date range of the search.",
    helpTopicSearchWorkspaceBullet9: "The blue summary above the buttons always describes in plain language what the current search is doing.",
    helpTopicSearchWorkspaceBullet10: "Run search starts the query, Load more fetches more pages, and Cancel stops longer local searches.",
    helpTopicSearchWorkspaceBullet11: "Saved searches, Clear search form, and Save search help you reuse recurring search forms locally.",
