    helpTopicAnalysisScoresTitle: "Understanding analysis scores",
    helpTopicAnalysisScoresText: "The analysis combines several methods because any single method can become overly generous or overly harsh on short or tightly themed text.",
    helpTopicAnalysisScoresBullet1: "Robustness mix: The overall score combines multiple stylometric methods into one cautious summary.",
    helpTopicAnalysisScoresBullet2: "Burrows's Delta: Compares frequent words stylistically; the lower the delta, the more similar the style.",
    helpTopicAnalysisScoresBullet3: "Cosine similarity: Compares frequent-word distributions as vectors; high values mean similar profiles.",
    helpTopicAnalysisScoresBullet4: "Jaccard similarity: Measures how strongly the word sets of both accounts overlap.",
    helpTopicAnalysisScoresBullet5: "Function-word profile: Compares small topic-light words like I, but, or and, which are often stylistically revealing.",
    helpTopicAnalysisScoresBullet6: "Character n-grams: Compares recurring character sequences and captures spelling habits and endings.",
    helpTopicAnalysisScoresBullet7: "Metrics profile: Summarises sentence length, word length, uppercase use, emojis, and similar baseline metrics.",
    helpTopicAnalysisPatternsTitle: "Understanding pattern cards",
    helpTopicAnalysisPatternsText: "The pattern cards show not only how similar two accounts are, but also what produces that impression.",
    helpTopicAnalysisPatternsBullet1: "Short words, two-word phrases, longer phrases, and function words reveal typical language building blocks.",
    helpTopicAnalysisPatternsBullet2: "Emoji profile, punctuation style, and common post starts or endings show recurring habits.",
    helpTopicAnalysisPatternsBullet3: "Word-length profile, writing conventions, link/hashtag/mention behaviour, and post structure describe formal style traits.",
