    archiveSpecEyebrow: "Workflow",
    archiveSpecTitle: "How the archive works",
    archiveSpecIntro: "First define the source, archive content, and a date range of up to three months, then load the desired state and create ZIP, HTML, or PDF outputs from it when needed.",
    archiveSpecItems: [
      "Start by choosing the source, date range, and archive type. In the PWA the date range is intentionally limited to at most three months.",
      "The source can be your own or another reachable account. After validation, Threadline shows its name, handle, and avatar.",
      "Then decide whether to load only that account's own material or also matching conversation context.",
      "After that, start a continuous fetch with `Load archive`. Threadline continues internally page by page, so you do not need to trigger separate waves.",
      "Under `Fetch and saved state`, you can reload a saved archive or reset the current state for a fresh run.",
      "Save the loaded state with `Save archive as ZIP` so posts, metadata, and images are stored as a backup file.",
      "SVG images are not embedded in the PWA archive for safety. A small placeholder image is stored instead.",
      "From there, create HTML, compact HTML, or PDF volumes. These exports always work from the already loaded state and do not start a new fetch.",
      "If you want to keep SVG on purpose or the full HTML becomes too large, use the PowerShell scripts from the script README instead. `-AllowSvg` re-enables SVG there deliberately; the SQLite variant with its own viewer is meant for large archives.",
      "Separate extra tools below handle single-thread exports, post checks, and media-only downloads."
    ],
