      "Lancez ensuite un chargement continu avec `Charger l'archive`. Threadline continue en interne page par page, sans que vous ayez \u00e0 d\u00e9clencher des vagues s\u00e9par\u00e9es.",
      "Dans `Chargement et \u00e9tat enregistr\u00e9`, vous pouvez recharger une archive sauvegard\u00e9e ou r\u00e9initialiser l'\u00e9tat actuel pour un nouveau lancement.",
      "Enregistrez l'\u00e9tat charg\u00e9 avec `Enregistrer l'archive en ZIP` afin de conserver posts, m\u00e9tadonn\u00e9es et images dans un fichier de sauvegarde.",
      "Vous pouvez ensuite g\u00e9n\u00e9rer une archive HTML pour la recherche hors ligne ou des volumes PDF pour une version lisible avec images et m\u00e9triques.",
